 "content": "def transform(grid):
    """Restore a rectangular 8-mask from the grid's vertical reflection/repeated rows."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == 8]
    if not cells:
        return g
    r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
    c0, c1 = min(c for _, c in cells), max(c for _, c in cells)
    # The mask is a complete rectangle; its rows belong to a vertically mirrored pattern.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            rr = r0 + r1 - r
            if g[rr][c] != 8:
                value = g[rr][c]
            else:
                # For the central self-paired rows, use the common value bracketed
                # by the nearest intact repeated rows when both sides agree.
                above = next((g[x][c] for x in range(r - 1, -1, -1) if g[x][c] != 8), None)
                below = next((g[x][c] for x in range(r + 1, h) if g[x][c] != 8), None)
                if above is not None and below is not None and above == below:
                    value = above
                elif above is not None and below is not None:
                    value = above if r - r0 <= r1 - r else below
                else:
                    value = above if above is not None else below
            g[r][c] = value
    return g

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
